+    private readonly List<NotificationItem> _allNotifications;
+    private int _revealedCount;
+
+    public NotificationService()
+    {
+        // Pre-generate a pool of fake notifications.
+        _allNotifications = Enumerable.Range(1, 100).Select(i => new NotificationItem
+        {
+            Id = i,
+            Message = $"Notification #{i} — something happened",
+            Timestamp = DateTime.UtcNow.AddMinutes(-100 + i)
+        }).ToList();
+
+        // Initially reveal the first 3.
+        _revealedCount = 3;
+    }
+
+    /// <summary>Returns the current set of visible notifications.</summary>
+    public Task<List<NotificationItem>> GetNotificationsAsync()
+    {
+        var items = _allNotifications.Take(_revealedCount).Reverse().ToList();
+        return Task.FromResult(items);
+    }
+
+    /// <summary>Reveals the next notification (simulates new data arriving).</summary>
+    public Task<List<NotificationItem>> CheckForNewNotificationsAsync()
+    {
+        if (_revealedCount < _allNotifications.Count)
+        {
+            _revealedCount++;
+        }
+        return GetNotificationsAsync();
+    }
+}
+

